REDLINES: List[Dict] = (
    _VAT_REDLINES + _INCOME_REDLINES + _COST_REDLINES + _FUND_REDLINES
    + _INVENTORY_REDLINES + _PAYROLL_REDLINES + _CIT_REDLINES
    + _COUNTERPARTY_REDLINES + _ASSET_REDLINES + _OTHER_REDLINES
    + _SPECIAL_TAX_REDLINES + _GAP_FILL_REDLINES + _A_CLASS_REDLINES
    + _OBLIGATION_REDLINES
)

_BY_ID: Dict[str, Dict] = {r["id"]: r for r in REDLINES}

DOMAIN_ORDER = [
    "发票", "收入", "成本", "成本费用", "资金", "存货", "工资社保",
    "关联交易", "所得税", "申报", "其他税费", "特定税种",
]


def all_redlines() -> List[Dict]:
    """返回全部红线（只读副本）"""
    return [dict(r) for r in REDLINES]


def get_redline(redline_id: str) -> Optional[Dict]:
    """按编号取红线"""
    r = _BY_ID.get(str(redline_id or "").strip())
    return dict(r) if r else None


def by_domain(domain: str) -> List[Dict]:
    """按风险域取红线"""
    return [dict(r) for r in REDLINES if r.get("domain") == domain]


def domains() -> List[str]:
    """已定义的风险域"""
    seen, out = set(), []
    for d in DOMAIN_ORDER:
        if any(r.get("domain") == d for r in REDLINES):
            seen.add(d)
            out.append(d)
    for r in REDLINES:
        d = r.get("domain")
        if d and d not in seen:
            seen.add(d)
            out.append(d)
    return out


# ── 红线配对打分（**唯一实现**，2026-09-25 根因修复）─────────────────────────
# 旧版把"税种名相同"也算 1 分，且**没有最低分数线**，于是只要得分为正就取第一名：
# 一条「增值税申报进项税额与进项发票税额月度差异」的发现，因为文本里含"增值税"，
# 而「固定资产取得、投用与折旧不匹配」红线的 taxes 里也有"增值税" → 得 1 分 → 被采纳为
# 该发现所属红线 → 报告随即用**固定资产折旧的构成要件**去论证一个增值税差异，
# 并写出"这些事实是从固定资产明细账、试生产记录、折旧计算表…核对出来的"（该企业
# 一份都没提交）。实测 13 条发现里 7 条配错红线。
# 现按**信号具体度**加权，并要求"必须命中名称主词或足够具体的提示词"才算对得上。
_MATCH_NAME_TITLE = 12        # 红线名称主词命中**发现标题**（最可靠）
_MATCH_NAME_TEXT = 8          # 名称主词命中全文
_MATCH_HINT_TITLE = 10        # 提示词命中标题
_MATCH_HINT_TEXT_LONG = 10    # 长提示词（≥4 字）命中全文
_MATCH_HINT_TEXT_SHORT = 3    # 短提示词（<4 字）命中全文——通用词，只作辅助
_MATCH_TAX = 1                # 税种名相同——极弱信号，**不可单独构成配对**
_MATCH_DOMAIN = 3             # 同域
# 可构成"对得上"的原因（其余分数只能作辅助，不能单独配对）
_STRONG_REASONS = ("name@title", "name@text", "hint@title", "hint@textL")


def score_redline(redline: Dict, title: str = "", text: str = "",
                  domain: Optional[str] = None) -> Tuple[int, List[str]]:
    """给"发现 ↔ 红线"打分，返回 `(分数, 命中原因列表)`。

    **唯一打分实现**：`match_redlines` 与 `match_redline_grounded` 都调它，
    避免"配对打分"在各处各写一套导致口径不一致。

    `title` 传发现的标题（`finding["type"]`）——标题命中比正文命中更可靠，
    故同一信号在标题里命中给更高分。
    """
    t = str(text or "")
    ti = str(title or "")
    s = 0
    why: List[str] = []
    main_word = (str(redline.get("name") or "").split("：")[0] or "").strip()
    if len(main_word) >= 3:
        if main_word in ti:
            s += _MATCH_NAME_TITLE
            why.append("name@title")
        elif main_word in t:
            s += _MATCH_NAME_TEXT
            why.append("name@text")
    for hint in (redline.get("match_hints") or []):
        hint = str(hint or "")
        if not hint:
            continue
        if hint in ti:
            s += _MATCH_HINT_TITLE
            why.append("hint@title")
        elif hint in t:
            if len(hint) >= 4:
                s += _MATCH_HINT_TEXT_LONG
                why.append("hint@textL")
            else:
                s += _MATCH_HINT_TEXT_SHORT
                why.append("hint@textS")
    for tax in (redline.get("taxes") or []):
        if tax and tax in t:
            s += _MATCH_TAX
    if domain and redline.get("domain") == domain:
        s += _MATCH_DOMAIN
    return s, why


def match_redlines(text: str, domain: Optional[str] = None, limit: int = 3,
                   title: str = "") -> List[Dict]:
    """
    依据发现文本匹配红线（按分数降序）。

    ⚠ 本函数**只做排序、不做采纳判断**。调用方若要用匹配结果去组织"红线级"结论
      （构成要件、证据链、定性），必须用 `match_redline_grounded()` —— 它会额外要求
      "信号足够具体"且"该红线所需资料本轮确实提供过"，否则返回未配对，
      以免把发现硬套到不相干的红线上。
    """
    t = str(text or "")
    if not t and not title:
        return []
    scored: List[Tuple[int, List[str], Dict]] = []
    for r in REDLINES:
        s, why = score_redline(r, title, t, domain)
        if s > 0:
            scored.append((s, why, r))
    scored.sort(key=lambda x: (-x[0], x[2]["id"]))
    out = []
    for s, why, r in scored[:limit]:
        d = dict(r)
        d["_score"] = s
        d["_reasons"] = list(why)
        out.append(d)
    return out


def match_redline_grounded(title: str, text: str,
                           available_materials: Optional[List[str]] = None,
                           domain: Optional[str] = None) -> Tuple[Optional[Dict], Dict]:
    """**可采纳**的红线配对：返回 `(红线或 None, 配对说明)`。

    两条硬条件（缺一不可）：
      ① **信号具体**：命中名称主词、或命中 ≥4 字的提示词、或提示词命中标题
         （仅靠"税种名相同/同域"不足以配对）；
      ② **资料可查**：该红线声明的 `required_materials` 与本轮**实际已提供**的资料
         有交集 —— 若一条红线所需的资料本轮一份都没有，就没有任何依据把它列为疑点，
         强行配上去只会让报告用不相干的构成要件去论证。

    不满足任一条 → `(None, {...})`，调用方应把该发现列为"未归入已知风险情形"，
    **不得**改挂到次优红线上。
    """
    avail = [str(a) for a in (available_materials or []) if a]
    t = str(text or "")
    ti = str(title or "")
    best: Optional[Tuple[int, List[str], Dict, List[str]]] = None
    for r in REDLINES:
        s, why = score_redline(r, ti, t, domain)
        if not any(w in _STRONG_REASONS for w in why):
            continue
        mats = [m for m in (r.get("required_materials") or []) if m in avail]
        if not mats:
            continue
        if best is None or s > best[0]:
            best = (s, why, r, mats)
    if best is None:
        return None, {
            "mode": "unmatched",
            "score": 0,
            "reasons": [],
            "materials": [],
            "note": "无信号足够具体且所需资料本轮有提供的红线",
        }
    s, why, r, mats = best
    return dict(r), {
        "mode": "matched",
        "score": s,
        "reasons": list(why),
        "materials": mats,
        "note": "按名称主词/具体提示词命中，且该红线所需资料本轮有提供",
    }


def stats() -> Dict:
    """红线库统计"""
    return {
        "version": KNOWLEDGE_VERSION,
        "total": len(REDLINES),
        "by_domain": {d: len(by_domain(d)) for d in domains()},
    }


# ═══════════════════════════════════════════════════════════════════════════
# ★ 2026-09-26 风险等级重排（按**证据强度**，用户复核后决定）
# ═══════════════════════════════════════════════════════════════════════════
# 背景（实测问题）：红线的风险等级原本由**其聚合的底层 finding 严重度**反推
#   （本文件本身**没有** level 字段），于是出现"倒挂"——
#   直接证据（资金回流 / 私户收款 / 银行收款>申报收入）被列**中风险**，
#   而结果指标（长期亏损仍持续经营）被列**高风险**。
#
# 原则：
#   ① **只覆盖已逐项论证的红线**；未列出的保持原逻辑 —— 不得为"看起来合理"批量改等级
#      （那等同反向的"随意调阈值"，是本项目反复禁止的行为）。
#   ② 每条必须写明**依据**：潜在税额 / 涉及金额 / 证据缺口 / 是否涉及虚开或偷税 / 补证紧迫性。
#   ③ 键用**红线编号**（稳定），不用显示名（会随文案调整而变）。
RISK_LEVEL_BASIS = {
    "RL-FUND-002": {
        "level": "高风险",
        "basis": "资金回流是虚开发票（资金空转、开票后回流）的**直接资金证据**：回流路径、"
                 "金额比例、时点均可由银行流水直接验证，证据缺口小；一旦坐实涉及虚开或偷税，"
                 "潜在增值税与企业所得税影响大，补证紧迫性高。",
    },
    "RL-INC-002": {
        "level": "高风险",
        "basis": "个人账户收取经营性款项是**隐匿收入的直接证据**（公私混同、不入账）："
                 "银行流水可逐笔验证，证据缺口小；涉及隐匿收入，潜在税额与滞纳金影响大。",
    },
    "RL-INC-001": {
        "level": "高风险",
        "basis": "银行收款大于申报收入直接指向**账外收入/少计销项**：两口径差额可量化，"
                 "证据缺口小，属税务机关认定隐匿收入的核心线索。",
    },
    "RL-VAT-006": {
        "level": "中风险",
        "basis": "未开票收入长期为零提示可能隐匿现金或个人客户收入，但属**单一指标**"
                 "（正常经营亦可能全部开票），须结合资金流与其他证据印证，故不列高风险。",
    },
    "RL-CIT-004": {
        "level": "中风险",
        "basis": "长期亏损仍持续经营是**结果指标**（可由收入不实、成本不实、转移利润等多种原因导致），"
                 "指向性不如资金类直接证据，须进一步查证后方可定性，故由高风险下调为中风险。",
    },
}


def risk_level_basis(rid):
    """取该红线的**等级重排依据**（按证据强度逐项论证）；未登记则返回 None（保持原逻辑）。"""
    return RISK_LEVEL_BASIS.get(str(rid or "").strip()) or None


# ══════════════════════════════════════════════════════════════════
# ★ 2026-09-29（点评整改 P0-6）红线「名称断言要件」表（数据驱动，单行可扩）
# ══════════════════════════════════════════════════════════════════
# 问题：一条红线是一个**要件包**，其 `name` 只概括**命名要件**。
#   例：RL-CIT-004 名称「长期亏损仍持续经营：收入或成本不实」，命名要件是"亏损"。
#   引擎的「企业所得税贡献率偏低」发现（financial_analyzer ④）只证明了该红线的
#   **第②项要件**（贡献率与经营规模不匹配），却把红线全名当标题 → 报告出现
#   与企业自身数据相矛盾的前提。外部点评实测：疑点标题「长期亏损仍持续经营」，
#   同项正文却写"净利润 402,368.09 元"（为正）、"申报亏损因申报表未取得未核对"。
#
# 通用规则（适用所有红线、所有行业、所有企业）：命中要件**不含命名要件**时，
#   标题必须裁剪到"企业自有的发现名 + 对应的红线与所涉要件序号"，
#   并显式声明**未就名称所断言的前提作出认定**。新增同类红线只需在此加一行。
_REDLINE_NAMING_CONSTITUENT = {
    # 红线编号: (命名要件序号元组, 名称所断言的前提短语)
    "RL-CIT-004": ((1, 4), "亏损"),
}


def trim_redline_title(redline_id, finding_type, constituent_hits, redline_name):
    """按实际成立的构成要件裁剪疑点标题（点评整改 P0-6）。

    返回 `(title, premise_note)`：
      · 命名要件已成立 / 该红线未登记命名要件 → 沿用红线名，`premise_note=""`；
      · 命名要件未成立（本轮只证明了其它要件） → 标题改为
        「<发现自有名称>（对应风险指标：<红线名>，本项仅涉及其第X项构成要件，
        未就「<前提>」作出认定）」，并返回 premise_note 供正文说明。
    判据只来自发现**自己的** constituent_hits（逐条判定证据），不额外推断。
    """
    rid = str(redline_id or "").strip()
    rname = str(redline_name or "").strip() or rid
    spec = _REDLINE_NAMING_CONSTITUENT.get(rid)
    if not spec:
        return rname, ""
    naming_idx, premise = spec
    hits = constituent_hits if isinstance(constituent_hits, list) else []
    idxs = set()
    for h in hits:
        if isinstance(h, dict):
            try:
                idxs.add(int(h.get("index")))
            except (TypeError, ValueError):
                continue
    if not idxs:
        # 无逐条判定证据 → 不足以支撑"本企业具备该前提"，按最保守口径裁剪
        pass
    elif idxs & set(naming_idx):
        return rname, ""
    _own = str(finding_type or "").strip()
    # 去掉"待核事实："等前缀，只留事实名，避免标题里出现两层标签
    for _p in ("待核事实：", "待核事实:", "线索：", "线索:"):
        if _own.startswith(_p):
            _own = _own[len(_p):].strip()
    _own = _own or rname
    _listed = "、".join("第%d项" % i for i in sorted(idxs)) if idxs else "所列"
    _clarify = (f"本项仅涉及该指标{_listed}构成要件，未就「{premise}」这一前提作出认定")
    if _own == rname or (rname and rname.startswith(_own)):
        # 发现自有名与红线名相同 → 不再重复一遍"对应风险指标"，只加认定范围括注
        title = f"{rname}（{_clarify}）"
    else:
        title = f"{_own}（对应风险指标：{rname}；{_clarify}）"
    note = (f"需要说明：本项认定范围仅限于上述构成要件，未就本风险指标名称中的"
            f"「{premise}」前提本身作出认定（该前提是否成立须以企业申报与账面数据另行核对）。")
    return title, note
